        //             "realized_pnl": "-0.993258849822",
        //             "realized_pnl_excl_fees": "-0.467",
        //             "is_transfer": false,
        //             "batch_status": "Settled",
        //             "trade_fee": "0.263075486855",
        //             "expected_rebate": "0",
        //             "tx_hash": "0x7a31fda53195c28f2e60bab189bb9e7bf0abffc55a4eceb13d5e307f70d6e892",
