    public function fetch_funding_rate_history(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): array {
        /**
         * fetches historical funding rate prices
         *
         * @see https://docs.derive.xyz/api-reference/market-data/publicget_funding_rate_history
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the funding rate history for
         * @param {int} [$since] $timestamp in ms of the earliest funding rate to fetch
         * @param {int} [$limit] the maximum amount of funding rate structures to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=funding-rate-history-structure funding rate structures~
         */
        if ($this->markets === null) {
            $this->load_markets();
        }
        $market = $this->market($symbol);
        $request = array(
            'instrument_name' => $market['id'],
        );
        if ($since !== null) {
            $request['start_timestamp'] = $since;
        }
        $until = $this->safe_integer($params, 'until');
        $paramsOmitted = $this->omit($params, array( 'until' ));
        if ($until !== null) {
            $request['end_timestamp'] = $until; // the venue silently ignores the to_timestamp spelling other endpoints use
        }
        $response = $this->publicPostGetFundingRateHistory($this->extend($request, $paramsOmitted));
        //
        //     {
        //         "id": "6dcdcdd2-1523-4d48-9b45-e1f3e61b3711",
        //         "result": {
        //             "instrument_name": null,
        //             "funding_rate_history": [
        //                 {
        //                     "timestamp": 1783461600000,
        //                     "risk_universe_id": 1,
        //                     "currency": "BTC",
        //                     "open": "0.000047348",
        //                     "high": "0.000047348",
        //                     "low": "0.000047348",
        //                     "close": "0.000047348",
        //                     "funding_rate": "0.000047348"
        //                 },
        //                 {
        //                     "timestamp": 1783465200000,
        //                     "risk_universe_id": 1,
        //                     "currency": "BTC",
        //                     "open": "0.000012500",
        //                     "high": "0.000049960",
        //                     "low": "0.000012500",
        //                     "close": "0.000049960",
        //                     "funding_rate": "0.000049960"
        //                 }
        //             ]
        //         }
        //     }
        //
        $result = $this->safe_dict($response, 'result', array());
        $data = $this->safe_list($result, 'funding_rate_history', array());
        $rates = array();
        for ($i = 0; $i < count($data); $i++) {
            $entry = $data[$i];
            $timestamp = $this->safe_integer($entry, 'timestamp');
            $rates[] = array(
                'info' => $entry,
                'symbol' => $market['symbol'],
                'fundingRate' => $this->safe_number($entry, 'funding_rate'),
                'timestamp' => $timestamp,
                'datetime' => $this->iso8601($timestamp),
            );
        }
        $sorted = $this->sort_by($rates, 'timestamp');
        return $this->filter_by_symbol_since_limit($sorted, $this->safe_string($market, 'symbol'), $since, $limit);
    }

    public function fetch_funding_rate(string $symbol, $params = array()): array {
        /**
         * fetch the current funding rate
         *
         * @see https://docs.derive.xyz/api-reference/market-data/publicget_funding_rate_history
         *
         * @param {string} $symbol unified market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=funding-rate-structure funding rate structure~
         */
        $response = $this->fetch_funding_rate_history($symbol, null, 1, $params);
        //
        //     [
        //         {
        //             "info": {
        //                 "timestamp": 1790870400000,
        //                 "risk_universe_id": 1,
        //                 "currency": "BTC",
        //                 "open": "0.000012500",
